<?php
require __DIR__.'/db.php';$pageTitle='Courses';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='create'){$st=$pdo->prepare('INSERT INTO courses(course_code,course_name,credits,dept_id,semester_no) VALUES(?,?,?,?,?)');$st->execute([$_POST['course_code'],$_POST['course_name'],$_POST['credits'],$_POST['dept_id'],$_POST['semester_no']]);$msg='Course created.';}elseif($a==='delete'){$st=$pdo->prepare('DELETE FROM courses WHERE course_id=?');$st->execute([$_POST['course_id']]);$msg='Course deleted.';}}catch(Throwable $e){$msg='Error: '.$e->getMessage();}}
$depts=$pdo->query('SELECT dept_id,dept_name FROM departments ORDER BY dept_name')->fetchAll();$rows=$pdo->query('SELECT c.*,d.dept_name FROM courses c JOIN departments d ON d.dept_id=c.dept_id ORDER BY c.semester_no,c.course_code')->fetchAll();include __DIR__.'/partials/header.php';
?>
<div class="hero"><div><h1>Courses</h1><p>Course master with credits and departmental mapping.</p></div></div><?php if($msg): ?><div class="notice success"><?=htmlspecialchars($msg)?></div><?php endif; ?><div class="form-card"><form method="post"><input type="hidden" name="action" value="create"><div class="form-grid"><div class="field"><label>Course Code</label><input name="course_code" required></div><div class="field"><label>Course Name</label><input name="course_name" required></div><div class="field"><label>Credits</label><input type="number" name="credits" min="1" max="8" required></div><div class="field"><label>Semester</label><input type="number" name="semester_no" min="1" max="8" required></div><div class="field"><label>Department</label><select name="dept_id"><?php foreach($depts as $d): ?><option value="<?=$d['dept_id']?>"><?=htmlspecialchars($d['dept_name'])?></option><?php endforeach; ?></select></div><div class="field"><button class="btn">Create Course</button></div></div></form></div><div class="table-wrap"><table class="table"><tr><th>ID</th><th>Code</th><th>Name</th><th>Credits</th><th>Department</th><th>Semester</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?=$r['course_id']?></td><td><?=$r['course_code']?></td><td><?=htmlspecialchars($r['course_name'])?></td><td><?=$r['credits']?></td><td><?=htmlspecialchars($r['dept_name'])?></td><td><?=$r['semester_no']?></td><td><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="course_id" value="<?=$r['course_id']?>"><button class="btn small danger">Delete</button></form></td></tr><?php endforeach; ?></table></div><?php include __DIR__.'/partials/footer.php'; ?>
